INSERT INTO hospital.services (code, name, category, department_id, description, is_active) VALUES ('18.0687.0058', 'Chụp và nút mạch điều trị u phổi [dưới DSA] Chưa bao gồm vật tư chuyên dụng dùng để can thiệp: bóng; bộ bơm áp lực, stent, các vật liệu nút mạch, keo nút mạch, các vi ống thông; các dây dẫn, vi dây dẫn, các vòng xoắn kim loại; dụng cụ để thả hoặc cắt vòng xoắn kim loại, lưới lọc tĩnh mạch, dụng cụ lấy dị vật, bộ dụng cụ lấy huyết khối, các loại ống thông trung gian hoặc chuyên dụng không thuộc ống thông dẫn đường và ống thông chẩn đoán (longsheat, ống thông siêu mềm), bộ dụng cụ bít (bộ thả dù, dù các loại), dụng cụ đóng lòng mạch (angioseal, perclose…).', 'intervention', NULL, NULL, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO hospital.services (code, name, category, department_id, description, is_active) VALUES ('18.0688.0058', 'Chụp và nút mạch điều trị u trung thất [dưới DSA] Chưa bao gồm vật tư chuyên dụng dùng để can thiệp: bóng; bộ bơm áp lực, stent, các vật liệu nút mạch, keo nút mạch, các vi ống thông; các dây dẫn, vi dây dẫn, các vòng xoắn kim loại; dụng cụ để thả hoặc cắt vòng xoắn kim loại, lưới lọc tĩnh mạch, dụng cụ lấy dị vật, bộ dụng cụ lấy huyết khối, các loại ống thông trung gian hoặc chuyên dụng không thuộc ống thông dẫn đường và ống thông chẩn đoán (longsheat, ống thông siêu mềm), bộ dụng cụ bít (bộ thả dù, dù các loại), dụng cụ đóng lòng mạch (angioseal, perclose…).', 'intervention', NULL, NULL, TRUE) ON CONFLICT (code) DO NOTHING;
