INSERT INTO hospital.services (code, name, category, department_id, description, is_active) VALUES ('10.0208.0403', 'Phẫu thuật Hybrid điều trị bệnh tim bẩm sinh (phẫu thuật tim + can thiệp tim mạch) Chưa bao gồm bộ tim phổi nhân tạo và dây chạy máy, vòng van và van tim nhân tạo, mạch máu nhân tạo, động mạch chủ nhân tạo, ống van động mạch, keo sinh học, quả lọc tách huyết tương và bộ dây dẫn, miếng vá siêu mỏng, dung dịch bảo vệ tạng, dây truyền dung dịch bảo vệ tạng.', 'procedure', NULL, NULL, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO hospital.services (code, name, category, department_id, description, is_active) VALUES ('10.0213.0392', 'Phẫu thuật bắc cầu động mạch chủ - động mạch vành có dùng máy tim phổi nhân tạo Chưa bao gồm bộ tim phổi nhân tạo và dây chạy máy, vòng van, van tim nhân tạo, miếng vá siêu mỏng, mạch máu nhân tạo, động mạch chủ nhân tạo, keo sinh học, quả lọc tách huyết tương và bộ dây dẫn, dung dịch bảo vệ tạng, dây truyền dung dịch bảo vệ tạng, dụng cụ cố định mạch vành, Shunt trong lòng động mạch.', 'procedure', NULL, NULL, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO hospital.services (code, name, category, department_id, description, is_active) VALUES ('10.0214.0395', 'Phẫu thuật bắc cầu động mạch chủ - động mạch vành không dùng máy tim phổi nhân tạo Chưa bao gồm mạch máu nhân tạo, động mạch chủ nhân tạo, keo sinh học.', 'procedure', NULL, NULL, TRUE) ON CONFLICT (code) DO NOTHING;
