INSERT INTO hospital.services (code, name, category, department_id, description, is_active) VALUES ('10.0216.0404', 'Phẫu thuật tách hẹp van hai lá Chưa bao gồm động mạch chủ Thành phố Hà Nội. Bảng giá áp dụng cho người bệnh có thẻ bảo hiểm y tế và không có thẻ bảo hiểm y tế. ĐƯƠNG tim kín lần đầu nhân tạo, van động mạch chủ nhân tạo, mạch máu nhân tạo, keo sinh học', 'procedure', NULL, NULL, TRUE) ON CONFLICT (code) DO NOTHING;
